INSERT INTO `club` VALUES (1,'Empowering minds to grow through logic, challenge, and innovation in competitive programming.','https://docs.google.com/spreadsheets/d/1NKYhrXOC3EAz1rGIa4MYPl1pQcqPAeOKsRU1dxP2oHM/edit','https://res.cloudinary.com/ckraglw8/image/upload/v1787584784/czcupsqohin9bki2qzk4.jpg','CP Club','2026-09-27 15:12:04.000000',_binary '',_binary ''),(2,'Software Engineering Club\n\nThe Software Engineering Club is where ideas become real products. It is dedicated to building, maintaining, and improving the software projects developed by ACM Alexandria Student Chapter.\n\nThe club is divided into two main tracks:\n\n* Project Development: Dedicated teams work together to design, develop, and launch new ACM projects from the ground up, following real-world software engineering practices.\n* Open Source Contribution: Members contribute to our existing projects by fixing bugs, implementing new features, improving performance, and helping maintain the software used by our community.\n\nThis club provides a practical environment to collaborate with other developers, work with modern development workflows, and gain hands-on experience through real projects that serve the chapter.\n\nNote: The Software Engineering Club is an internal club, meaning only ACM Alexandria Student Chapter members are eligible to join.','https://docs.google.com/spreadsheets/d/108_bxu6ZCpPC3H2VWDW9pPQdYJ8BT1kOeo5MRWG5BAQ/edit','https://res.cloudinary.com/ckraglw8/image/upload/v1787584846/kdiotpxypuyfzuwove18.jpg','Software Engineering Club','2026-09-26 09:24:09.000000',_binary '\0',_binary '');
/*!40000 ALTER TABLE `club` ENABLE KEYS */;
UNLOCK TABLES;

