INSERT INTO `committee` VALUES (1,'Plans and executes engaging events, workshops, competitions, and social activities that create valuable experiences for members.',_binary '\0','https://res.cloudinary.com/ckraglw8/image/upload/v1787584253/gmqycfhnhmdfmic6qsph.jpg','Training & Development Committee',10),(2,'Ensures every event runs smoothly by managing logistics, coordinating teams, organizing event operations, and making sure every detail is planned and executed efficiently.',_binary '\0','https://res.cloudinary.com/ckraglw8/image/upload/v1787584675/oc0cyh1zhoccejrvdrbk.jpg','Organization Committee',11),(3,'Creates visual and digital content, including photography, videography, graphic design, and social media coverage to showcase the chapterâ€™s activities.',_binary '\0','https://res.cloudinary.com/ckraglw8/image/upload/v1787584414/zqxp99mycaj9rxveeydn.jpg','Media Committee',12),(4,'Builds the chapterâ€™s public image by managing partnerships, sponsorships, outreach, and communication with external organizations.',_binary '\0','https://res.cloudinary.com/ckraglw8/image/upload/v1787584449/gvziffaab25fnkz2b5d7.jpg','PR Committee ',22),(5,'Focuses on member recruitment, onboarding, team development, and fostering a supportive and collaborative chapter culture.',_binary '\0','https://res.cloudinary.com/ckraglw8/image/upload/v1787584633/gdwjoswzmcqglg9nrolw.jpg','HR Committee',24);
