INSERT INTO `event` VALUES (1,'SSP Building A4','Join us for an electrifying event as we roll out the red carpet and welcome the newest members of Computer and Systems Engineering Department (CSED)!\nHere\'s what you can expect:\nPower-Up Sessions: Dive into interactive orientation sessions led by our brilliant faculty, staff and senior students. They will guide you through the labyrinth of academic programs, unveiling the secrets of our cutting-edge curriculum and revealing the keys to unlocking your full potential. ğŸ—ğŸ“š\nChoose Your Quest: Unearth the fantastic array of courses and specialized tracks available to you in the world of computer and systems engineering. With countless quests to embark upon, you\'ll discover the areas where your talents truly shine. ğŸ”\nGame On: Prepare for an epic networking experience! Engage in thrilling conversations, team up with current students, and forge connections that will level up your university life. You\'ll be part of a vibrant community where collaboration and camaraderie reign supreme. ğŸ’¬\nRemember, this is just the beginning of your extraordinary adventure at CSED. LEVEL UP will guide you through the first steps of your journey, ensuring a smooth transition and providing you with the support you need to thrive.\nSo, mark your calendars, charge up your enthusiasm, and get ready to LEVEL UP! We can\'t wait to welcome you into our extraordinary CSED family. ğŸ“ğŸ’»','2025-09-10 00:00:00.000000',NULL,'https://res.cloudinary.com/ckraglw8/image/upload/v1787587360/hq10jgqfexo3021u9ilu.jpg','Level Up \'25',NULL,_binary '\0'),(2,'Creetiva- ITI','Attention CSED & CCE ! ğŸ“¢\nEver wished someone could tell you how they handled a tricky situation before you face it yourself?\nNeed advice on a specific course, an upcoming internship, or just curious about different career paths ?\nThatâ€™s exactly why We are excited to announce ACM Exchange ! ğŸ‰\nA space where all your questions, whether about courses, internships, or future fields. Get real answers from people whoâ€™ve been in your shoes and are ready to share their experience.\n','2025-10-02 10:00:00.000000',NULL,'https://res.cloudinary.com/ckraglw8/image/upload/v1787586113/u0gz4teng2bpkwvfexkr.jpg','ACM Exchange',NULL,_binary '\0'),(3,'Wajan Workingspace','ğŸš€ğŸŒŒ Future youthâ€¦ are you ready to explore CS Week? ğŸŒŒğŸš€\nPrepare to launch into a world where Computer Engineering comes to life.\nCS Week is a journey designed for future engineers who build systems, shape technology, and push boundaries, guided by the adventurous spirit we grew up with.\nThis is not just talks and games.\nItâ€™s an exploration of how engineering thinking meets the future.\nğŸ”§ What Awaits You\nğŸ—„ï¸ Databases\nDive into the core of system design, where data, structure, and problem-solving come together through interactive challenges.\nğŸ¤– Artificial Intelligence: Threat or Tool?\nAn honest discussion about AI in the engineering world, will it replace us, or amplify what we build?\nğŸ§  AI Agents\nExplore how intelligent agents work, communicate, and make decisions, and why they matter to modern software and systems engineering.\nğŸ›°ï¸ Git\nLearn how real engineers manage code, teams, and large-scale projects using version control.\nâ˜ï¸ Cloud Computing\nLearn how modern applications are deployed, scaled, and managed in the cloud, and why every engineer needs this skill.\nğŸ® Games & Challenges\nBecause every mission needs strategy, teamwork, and a bit of fun.\nğŸ“£ Stay Tuned for Updates!\n- Weâ€™ll soon reveal:\n- Venue details\n- Event schedules\n- Distinguished speakers\nğŸ“Œ Mark your calendars and keep an eye out for announcements!\nReady to be part of this unforgettable journey?','2026-02-09 09:00:00.000000',NULL,'https://res.cloudinary.com/ckraglw8/image/upload/v1787586582/ohbgczooje5m5poqfxst.jpg','CS Week - Sixth Edition',NULL,_binary '\0'),(4,'SSP Building A4 ','Every great graduation project starts with the right direction. ğŸ“\nIf youâ€™re about to begin your journey, this is your chance to understand what really matters, from choosing the right idea, to building, managing, and delivering a project youâ€™ll actually be proud of.','2026-04-30 08:30:00.000000',NULL,'https://res.cloudinary.com/ckraglw8/image/upload/v1787586809/frvfrdtssqiyejpzbso7.jpg','Graduation Project \'26 Info Session',NULL,_binary '\0'),(7,'ORA Academy','ACM Alexandria Student Chapter is bringing you our first-ever Agentic AI Bootcamp & Hackathon! ğŸ¤–ğŸ§¡\n\nAnd weâ€™re kicking things off with someone who knows exactly what it takes to build with AI.\n\nMeet Yusuf Morsi, an AI/ML engineer and 8x hackathon winner currently working on ML and RAG systems at Cisco, while also building agentic AI solutions for supply chain. His experience spans production AI systems, machine learning, RAG, and multi-agent architectures, alongside an impressive track record of winning major hackathons, including competitions at Cambridge, Stanford, UCLA, and more.\n\nOn September 7th & 8th, Yusuf will be leading interactive sessions and live demos focused on how to use Agentic AI efficiently, move beyond simply prompting AI, and actually build useful systems with it.\n\nThen, on September 9th, itâ€™s time to put those skills into action. ğŸš€\n\nOur Hackathon will give you the chance to build your own ideas, with free AI tokens provided by one of our special sponsors to cover your needs throughout the competition. Teams will consist of 2 to 4 members, and if you donâ€™t have a team yet, donâ€™t worry! Weâ€™ll help you find teammates and form a team.\n\nğŸ“ Venue: ORA Academy\nhttps://maps.app.goo.gl/vmZ8qD4v6yGRiWua8?g_st=ic\n\nğŸ’° Fees: 200 EGP\n\nDonâ€™t miss the chance to learn from an experienced AI builder, then put what you learn to the test the very next day.','2026-09-07 12:00:00.000000','https://docs.google.com/spreadsheets/d/17_EEc0ftMHSIWyJV7-7DxHXH9TkNc1wFotx6Dwwtwpo/edit','https://res.cloudinary.com/ckraglw8/image/upload/v1789096700/zyoxlz4ssfef3aonukax.png','Agentic AI Bootcamp &Hackathon','2026-09-11 03:21:32.000000',_binary '\0'),(8,'304','Welcome to CSED!\n\nTo all CSED \'29 newcomers: welcome to Computer & Systems Engineering! ğŸ’»âœ¨\n\nStepping into the department can feel like entering a whole new world, but you don\'t have to navigate it alone. Join us for LEVEL UP, an exclusive orientation event designed to give you a complete roadmap and first look into everything CSED! ğŸ›ï¸\n\nWeâ€™ve brought together an incredible panel of speakers, industry professionals and TAs, to share their experiences, guide your path, and answer all your questions:\nğŸ™ï¸ Moâ€™men Hamdy (Senior I @ Trianglz | TA @ FOE-AU | CSED \'23)\nğŸ™ï¸ Mostafa Galal (SDE I @ Noon | TA @ FOE-AU | CSED \'25)\nğŸ™ï¸ Youssef Bazina (SWE @ Bloompath | TA @ FOE-AU | CSED \'24)','2026-09-24 12:30:00.000000',NULL,'https://res.cloudinary.com/ckraglw8/image/upload/v1790271270/vgfbnb7mzvludqnnj7f5.png','Level Up 2026',NULL,_binary '\0');
/*!40000 ALTER TABLE `event` ENABLE KEYS */;
UNLOCK TABLES;

