INSERT INTO `exclusive_form_questions` VALUES (1,_binary '','Are you member in SWE Club?','CHECKBOX',1),(2,_binary '','What are Backend frameworks you are familiar with?','TEXT',1),(3,_binary '','What are Frontend frameworks you are familiar with?','TEXT',1),(4,_binary '','Are you familiar with database design?','MULTIPLE_CHOICE',1),(5,_binary '','What is the area you like working in most?','MULTIPLE_CHOICE',1),(6,_binary '','Which AI Tools you usually use in planning or implementing','TEXT',1),(7,_binary '','Write a brief about the most interesting project you have worked on and what technologies you used in it?','TEXT',1),(9,_binary '','If we start developing a mobile version of TaskStream with Flutter, Would you be interested in participating in thing like that?','MULTIPLE_CHOICE',1),(10,_binary '\0','Your CV Link (Optional)(Make sure we can access it)','TEXT',1),(12,_binary '','What is your Committee?','MULTIPLE_CHOICE',2),(15,_binary '','What do you think the most important skill for a host ?','TEXT',2),(16,_binary '','How do you rate your hosting skills from 5 ?','MULTIPLE_CHOICE',2),(17,_binary '','How do you handle a boring episode/Guest ?','TEXT',2),(18,_binary '','Do you have a specific field you prefer to host the episode about ?','MULTIPLE_CHOICE',2),(19,_binary '\0','If you have a specific field mention it','TEXT',2),(20,_binary '\0','Any additional notes','TEXT',2),(21,_binary '','Are you member in SWE Club?','CHECKBOX',3),(22,_binary '','What are Backend frameworks you are familiar with?','TEXT',3),(23,_binary '','What are Frontend frameworks you are familiar with?','TEXT',3),(24,_binary '','Are you familiar with database design?','MULTIPLE_CHOICE',3),(25,_binary '','What is the area you like working in most?','MULTIPLE_CHOICE',3),(26,_binary '','Which AI Tools you usually use in planning or implementing? and how do you use it','TEXT',3),(27,_binary '','Write a brief about the most interesting project you have worked on and what technologies you used in it?','TEXT',3),(28,_binary '\0','Your CV Link (Optional)(Make sure we can access it)','TEXT',3),(29,_binary '\0','Have you participated in a Technical team before?','MULTIPLE_CHOICE',4),(30,_binary '\0','If yes write about your experience and what was your role in the team','TEXT',4),(31,_binary '\0','Your CV URL (Make sure its accessable)','TEXT',4),(32,_binary '','Name','TEXT',5),(33,_binary '','Batch','TEXT',5),(34,_binary '\0','Committee','TEXT',5),(35,_binary '','Are you a member of SWE Club?','CHECKBOX',6),(36,_binary '','What mobile development technologies/frameworks are you familiar with?','TEXT',6),(37,_binary '','Which mobile platform are you most interested in?','MULTIPLE_CHOICE',6),(38,_binary '','Which of the following are you familiar with?','CHECKBOX',6),(39,_binary '','Which AI tools do you usually use while planning or implementing software projects?','TEXT',6),(40,_binary '','Have you worked on a mobile application before?','MULTIPLE_CHOICE',6),(41,_binary '\0','Your CV Link','TEXT',6);
