INSERT INTO `program` VALUES (1,'Ready to sharpen your problem-solving skills and dive into the world of Competitive Programming?\nJoin ACM Alexandria\'s Competitive Programming Summer Training, where you\'ll learn the fundamentals of algorithms and data structures, practice solving real programming challenges, and build the mindset needed for programming contests and technical interviews.\nWhether you\'re just getting started or already have some experience, our training is designed with two levels to help you progress at your own pace.\nWhat to expect\nğŸ’¡ Interactive sessions \nğŸ† A reward system to keep you motivated\nğŸ§© Weekly problem-solving practice\nğŸ¤ A supportive community to learn and grow with\n','2026-09-05 10:00:00.000000',NULL,'https://res.cloudinary.com/ckraglw8/image/upload/v1787587825/kckxgyvzayzj9bhsgjef.jpg','CP Summer Training \'26',_binary '\0',NULL,'2026-07-04 07:00:00.000000','Every Saturday 1:00 PM');
